class QuickSort(SortStrategy):
    def sort(self, data):
        if len(data) <= 1:
            return data
        pivot = data[0]
        return (
            self.sort([x for x in data[1:] if x < pivot])
            + [pivot]
            + self.sort([x for x in data[1:] if x >= pivot])
        )

